// The bundled case library (examples/library.json, generated by
// tools/make-library.mjs): one card per case, in the UI language, with the
// player's own progress (solved / best time) read from the local stores.
import { el } from "../util/dom.js";
import { difficultyLabel } from "../model/puzzle.js";
import { formatElapsed } from "../util/time.js";
import * as store from "../storage/puzzleStore.js";
import * as achievementsStore from "../storage/achievementsStore.js";
import { getLanguage, t } from "../i18n/i18n.js";

export const LIBRARY_ID_PREFIXES = ["lib_", "tutorial_"];

export function isLibraryPuzzleId(id) {
  return typeof id === "string" && LIBRARY_ID_PREFIXES.some((p) => id.startsWith(p));
}

export async function loadLibraryIndex() {
  const res = await fetch("examples/library.json");
  if (!res.ok) throw new Error(`library index: ${res.status}`);
  const data = await res.json();
  return (data.cases || []).slice().sort((a, b) => a.order - b.order);
}

// Pure: what to show for one library entry, given the language and a lookup
// of the player's solve records. Kept separate from the DOM so it's testable.
export function describeLibraryEntry(entry, lang, solves, savedIds) {
  const puzzleId = entry.puzzleId?.[lang];
  const solve = puzzleId ? solves[`puzzle:${puzzleId}`] : null;
  return {
    id: entry.id,
    title: entry.title[lang] ?? entry.title.en,
    difficulty: entry.difficulty,
    size: `${entry.size[0]}×${entry.size[1]}`,
    characters: entry.characters,
    solved: !!solve,
    bestElapsedSeconds: solve?.bestElapsedSeconds ?? null,
    href: puzzleId && savedIds.has(puzzleId) ? `player.html?id=${encodeURIComponent(puzzleId)}` : `player.html?import=${encodeURIComponent(entry.files[lang])}`,
  };
}

// One case per day, the same for everyone on the same (UTC) date, cycling
// through the library (the tutorial is excluded: it is for newcomers).
export function caseOfTheDay(entries, date = new Date()) {
  const pool = entries.filter((e) => e.id !== "tutorial");
  if (pool.length === 0) return null;
  const day = Math.floor(date.getTime() / 86_400_000);
  return pool[day % pool.length];
}

export async function renderLibrarySection(parent) {
  let entries;
  try {
    entries = await loadLibraryIndex();
  } catch {
    return; // offline before first visit, or hosted without examples/: just skip the section
  }
  const lang = getLanguage();
  const solves = achievementsStore.getRawData().solves;
  const savedIds = new Set(store.list().map((p) => p.id));
  const panel = el("div", { class: "panel library-list" });
  for (const entry of entries) {
    const d = describeLibraryEntry(entry, lang, solves, savedIds);
    panel.appendChild(
      el("div", { class: "saved-row" }, [
        el("div", {}, [
          el("span", { class: "title" }, [d.solved ? el("span", { class: "completed-badge", title: t("Completato") }, "✓") : null, d.title]),
          d.difficulty ? el("span", { class: `difficulty-badge difficulty-${d.difficulty}` }, difficultyLabel(d.difficulty)) : null,
          d.bestElapsedSeconds != null ? el("span", { class: "best-time-badge", title: t("Miglior tempo") }, `⏱ ${formatElapsed(d.bestElapsedSeconds)}`) : null,
          el("span", { class: "meta" }, t("Griglia {size} · {count} personaggi", { size: d.size, count: d.characters })),
        ]),
        el("div", { class: "actions" }, [el("a", { class: "play", href: d.href }, d.solved ? t("Rigioca") : t("Gioca"))]),
      ])
    );
  }
  const today = caseOfTheDay(entries);
  const todayInfo = today ? describeLibraryEntry(today, lang, solves, savedIds) : null;
  parent.appendChild(
    el("section", { class: "library-section" }, [
      todayInfo
        ? el("div", { class: "panel case-of-the-day" }, [
            el("span", { class: "resume-label" }, t("📅 Caso del giorno")),
            " ",
            el("strong", {}, todayInfo.title),
            " ",
            el("a", { class: "play", href: todayInfo.href }, todayInfo.solved ? t("Rigioca") : t("Gioca")),
          ])
        : null,
      el("div", { class: "saved-list-header" }, [el("h2", {}, t("Casi inclusi"))]),
      panel,
    ])
  );
}
